using System;
using System.IO;
using System.Numerics;
using System.Collections.Generic;
public static class WeightedPairs {
 struct Node {public ulong AndBad,OrGood;public int L,R,Start,End;}
 static Node[] tree;static int nodes;static ulong[] fs,ys;static int[] ids,ts,lut;static ulong Bad,Good;static int threshold;static long visits,pairs;static bool found,limited;static ulong hit;static int hitA,hitB,hitT;static System.Diagnostics.Stopwatch clock;static int seconds;
 public static void Weights(string file){var w=new int[64];using(var r=new BinaryReader(File.OpenRead(file))){for(int i=0;i<64;i++){w[i]=r.ReadInt32();if(w[i]<0)throw new Exception("negative weight");}}lut=new int[8*256];for(int k=0;k<8;k++)for(int v=1;v<256;v++){int b=BitOperations.TrailingZeroCount((uint)v);lut[k*256+v]=lut[k*256+(v&(v-1))]+w[k*8+b];}}
 public static int Weight(ulong f){int sum=0;for(int k=0;k<8;k++){sum+=lut[k*256+(int)(f&255)];f>>=8;}return sum;}
 static int Build(int lo,int hi){int ix=nodes++;Node v=new Node{Start=lo,End=hi,L=-1,R=-1};if(ys[lo]==ys[hi-1]){v.AndBad=ys[lo];for(int i=lo;i<hi;i++)v.OrGood|=fs[i]&Good;}else{int bit=63-BitOperations.LeadingZeroCount(ys[lo]^ys[hi-1]);ulong boundary=(ys[lo]&(~0UL<<bit))|(1UL<<bit);int a=lo,b=hi;while(a<b){int m=(a+b)>>1;if(ys[m]<boundary)a=m+1;else b=m;}if(a<=lo||a>=hi)throw new Exception("split");v.L=Build(lo,a);v.R=Build(a,hi);v.AndBad=tree[v.L].AndBad&tree[v.R].AndBad;v.OrGood=tree[v.L].OrGood|tree[v.R].OrGood;}tree[ix]=v;return ix;}
 static void Join(int ai,int bi){if(found||limited)return;visits++;if(visits%10000000==0){Console.WriteLine($"weighted join visits={visits} pairs={pairs} seconds={clock.Elapsed.TotalSeconds:F2}");if(seconds>0&&clock.Elapsed.TotalSeconds>seconds){limited=true;return;}}ref Node a=ref tree[ai];ref Node b=ref tree[bi];if((a.AndBad&b.AndBad)!=0||Weight(a.OrGood&b.OrGood)<threshold)return;if(ai==bi&&a.L>=0){Join(a.L,a.L);Join(a.L,a.R);Join(a.R,a.R);return;}if(a.L<0&&b.L<0){for(int i=a.Start;i<a.End&&!found;i++)for(int j=ai==bi?i:b.Start;j<b.End;j++){pairs++;ulong cover=fs[i]&fs[j];if(Weight(cover&Good)>=threshold){if((cover&Bad)!=0)throw new Exception("unsafe");found=true;hit=cover;hitA=ids[i];hitB=ids[j];hitT=Math.Max(ts[i],ts[j]);break;}}return;}if(a.L>=0&&(b.L<0||a.End-a.Start>=b.End-b.Start)){Join(a.L,bi);Join(a.R,bi);}else{Join(ai,b.L);Join(ai,b.R);}}
 public static void Run(string image,string output,string weights,ulong forbidden,int minimum,int cutoff,int limit){Weights(weights);Bad=forbidden;Good=~Bad;threshold=minimum;visits=pairs=0;nodes=0;found=limited=false;hit=0;hitA=hitB=-1;hitT=0;seconds=limit;clock=System.Diagnostics.Stopwatch.StartNew();var vf=new List<ulong>();var vi=new List<int>();var vt=new List<int>();int total;
 using(var r=new BinaryReader(File.OpenRead(image))){if(r.ReadInt32()!=0)throw new Exception("partial input image");total=r.ReadInt32();for(int i=0;i<total;i++){ulong f=r.ReadUInt64();int t=r.ReadInt32();r.BaseStream.Position+=20;if(t<=cutoff&&Weight(f&Good)>=threshold){vf.Add(f);vi.Add(i);vt.Add(t);}}}
 int count=vf.Count;ys=new ulong[count];ids=vi.ToArray();fs=vf.ToArray();ts=vt.ToArray();var perm=new int[count];for(int i=0;i<count;i++){ys[i]=fs[i]&Bad;perm[i]=i;}Array.Sort(ys,perm);var nf=new ulong[count];var ni=new int[count];var nt=new int[count];for(int i=0;i<count;i++){nf[i]=fs[perm[i]];ni[i]=ids[perm[i]];nt[i]=ts[perm[i]];}fs=nf;ids=ni;ts=nt;vf.Clear();vi.Clear();vt.Clear();tree=new Node[2*count];if(count>0)Build(0,count);Console.WriteLine($"weighted built inputs={count} nodes={nodes} seconds={clock.Elapsed.TotalSeconds:F2}");if(count>0)Join(0,0);
 File.WriteAllText(output,System.Text.Json.JsonSerializer.Serialize(new{status=found?"SAT_WEIGHT_THRESHOLD":limited?"UNKNOWN_TIME_LIMIT":"COMPLETE_NO_WEIGHT_THRESHOLD",forbidden,minimum,cutoff,total_inputs=total,filtered_inputs=count,nodes,visits,pairs,cover=hit,weight=found?Weight(hit):0,input_a=hitA,input_b=hitB,maximum_input_fee_fs=hitT,seconds=clock.Elapsed.TotalSeconds}));
 }
 sealed class Hash:IEqualityComparer<ulong>{public bool Equals(ulong a,ulong b)=>a==b;public int GetHashCode(ulong x){unchecked{x^=x>>30;x*=0xbf58476d1ce4e5b9UL;x^=x>>27;x*=0x94d049bb133111ebUL;x^=x>>31;return(int)x;}}}
 public static void Products(string input,string output,string weights,ulong good,int cutoff,int minimum){Weights(weights);var fs=new List<ulong>();var ts=new List<int>();var ids=new List<int>();using(var r=new BinaryReader(File.OpenRead(input))){int n=r.ReadInt32();for(int i=0;i<n;i++){ulong f=r.ReadUInt64();int t=r.ReadInt32();if(t<=cutoff&&Weight(f&good)>=minimum){fs.Add(f);ts.Add(t);ids.Add(i);}}}var im=new Dictionary<ulong,(int t,int a,int b)>(new Hash());long pairs=0;for(int a=0;a<fs.Count;a++)for(int b=a;b<fs.Count;b++){pairs++;ulong f=fs[a]&fs[b];if(Weight(f&good)<minimum)continue;int t=Math.Max(ts[a],ts[b]);if(!im.TryGetValue(f,out var old)||t<old.t)im[f]=(t,ids[a],ids[b]);}using(var w=new BinaryWriter(File.Create(output))){w.Write(0);w.Write(im.Count);foreach(var q in im){w.Write(q.Key);w.Write(q.Value.t);w.Write(-2);w.Write(q.Value.a);w.Write(q.Value.b);w.Write(-1);w.Write(-1);}}File.WriteAllText(output+".json",System.Text.Json.JsonSerializer.Serialize(new{status="COMPLETE_WEIGHTED_SYMBOLIC_PRODUCTS",cutoff,minimum,inputs=fs.Count,pairs,functions=im.Count}));}
}
